from AlgorithmImport import *

class MyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to equities at daily resolution
        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            symbol = self.AddEquity(ticker, Resolution.Daily).Symbol
            self.symbols[ticker] = symbol

        # Strategy A state (SPY)
        self.strategyA_shares = 0
        self.strategyA_prev_spy_close = None
        self.strategyA_prev_spy_sma = None

        # Strategy B state (AAPL)
        self.strategyB_shares = 0
        self.strategyB_prev_aapl_close = None
        self.strategyB_consecutive_red_days = 0

        # Indicators
        self.spy_sma = self.SMA(self.symbols["SPY"], 50, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.symbols["AAPL"], 14, Resolution.Daily)

    def OnData(self, data):
        # If any subscribed ticker has missing data, skip all rule evaluation
        for ticker in self.tickers:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        # Get current data
        spy_close = data[self.symbols["SPY"]].Close
        spy_sma = self.spy_sma.Current.Value
        aapl_close = data[self.symbols["AAPL"]].Close
        aapl_rsi = self.aapl_rsi.Current.Value

        # Update consecutive red days counter for AAPL
        if self.strategyB_prev_aapl_close is not None:
            if aapl_close < self.strategyB_prev_aapl_close:
                self.strategyB_consecutive_red_days += 1
            else:
                self.strategyB_consecutive_red_days = 0

        # Do not trade until all indicators are ready
        if self.spy_sma.IsReady and self.aapl_rsi.IsReady:
            # Strategy A: SMA crossover on SPY
            # Evaluate sell before buy
            if self.strategyA_shares > 0:
                if self.strategyA_prev_spy_close is not None and self.strategyA_prev_spy_sma is not None:
                    # Sell if SPY close crosses below SMA
                    if self.strategyA_prev_spy_close > self.strategyA_prev_spy_sma and spy_close <= spy_sma:
                        self.MarketOrder(self.symbols["SPY"], -self.strategyA_shares)
                        self.strategyA_shares = 0

            if self.strategyA_shares == 0:
                if self.strategyA_prev_spy_close is not None and self.strategyA_prev_spy_sma is not None:
                    # Buy if SPY close crosses above SMA
                    if self.strategyA_prev_spy_close <= self.strategyA_prev_spy_sma and spy_close > spy_sma:
                        portfolio_value = self.Portfolio.TotalPortfolioValue
                        invest_amount = portfolio_value * 0.4
                        shares_to_buy = int(invest_amount / spy_close)
                        if shares_to_buy > 0:
                            self.MarketOrder(self.symbols["SPY"], shares_to_buy)
                            self.strategyA_shares = shares_to_buy

            # Strategy B: Red days + RSI on AAPL
            # Evaluate sell before buy
            if self.strategyB_shares > 0:
                # Sell if RSI > 60
                if aapl_rsi > 60:
                    self.MarketOrder(self.symbols["AAPL"], -self.strategyB_shares)
                    self.strategyB_shares = 0

            if self.strategyB_shares == 0:
                # Buy if AAPL has been red for 3 consecutive days
                if self.strategyB_consecutive_red_days >= 3:
                    available_cash = self.Portfolio.Cash
                    if available_cash >= 20000:
                        shares_to_buy = int(20000 / aapl_close)
                        if shares_to_buy > 0:
                            self.MarketOrder(self.symbols["AAPL"], shares_to_buy)
                            self.strategyB_shares = shares_to_buy

        # Update state for next bar
        self.strategyA_prev_spy_close = spy_close
        self.strategyA_prev_spy_sma = spy_sma
        self.strategyB_prev_aapl_close = aapl_close

