class Algorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to all required US equities
        self.symbols_to_subscribe = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbol_dict = {}
        for symbol_str in self.symbols_to_subscribe:
            self.symbol_dict[symbol_str] = self.AddEquity(symbol_str, Resolution.Daily).Symbol

        self.spy = self.symbol_dict["SPY"]
        self.aapl = self.symbol_dict["AAPL"]

        # Strategy A (SPY)
        self.sma_spy = self.SMA(self.spy, 20, Resolution.Daily)
        self.strategy_a_prev_close = None
        self.strategy_a_prev_sma = None

        # Strategy B (AAPL)
        self.rsi_aapl = self.RSI(self.aapl, 14, Resolution.Daily)
        self.strategy_b_red_days = 0
        self.strategy_b_prev_close = None

    def OnData(self, data):
        # Check if all required symbols have data
        if not all(self.symbol_dict[s] in data for s in self.symbols_to_subscribe):
            return

        spy_close = self.Securities[self.spy].Close
        aapl_close = self.Securities[self.aapl].Close

        # Get current positions
        spy_position = self.Portfolio[self.spy].Quantity
        aapl_position = self.Portfolio[self.aapl].Quantity

        # Strategy A (SPY)
        # Sell first (if holding)
        if spy_position > 0:
            if self.sma_spy.IsReady and self.strategy_a_prev_sma is not None:
                curr_sma = self.sma_spy.Current.Value
                # Check if crosses below: prev_close >= prev_sma AND curr_close < curr_sma
                if self.strategy_a_prev_close >= self.strategy_a_prev_sma and spy_close < curr_sma:
                    self.Liquidate(self.spy)

        # Buy (if not holding)
        if spy_position == 0:
            if self.sma_spy.IsReady and self.strategy_a_prev_sma is not None:
                curr_sma = self.sma_spy.Current.Value
                # Check if crosses above: prev_close <= prev_sma AND curr_close > curr_sma
                if self.strategy_a_prev_close <= self.strategy_a_prev_sma and spy_close > curr_sma:
                    # Invest 40% of portfolio
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    amount = portfolio_value * 0.4
                    shares = int(amount / spy_close)
                    if shares > 0:
                        self.MarketOrder(self.spy, shares)

        # Strategy B (AAPL)
        # Update red days count
        if self.strategy_b_prev_close is not None:
            if aapl_close < self.strategy_b_prev_close:
                self.strategy_b_red_days += 1
            else:
                self.strategy_b_red_days = 0

        # Sell first (if holding)
        if aapl_position > 0:
            if self.rsi_aapl.IsReady:
                rsi_value = self.rsi_aapl.Current.Value
                if rsi_value > 60:
                    self.Liquidate(self.aapl)

        # Buy (if not holding)
        if aapl_position == 0:
            if self.strategy_b_red_days >= 3:
                # Buy $20,000 if cash available
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.MarketOrder(self.aapl, shares)

        # Update previous values for next bar
        self.strategy_a_prev_close = spy_close
        if self.sma_spy.IsReady:
            self.strategy_a_prev_sma = self.sma_spy.Current.Value

        self.strategy_b_prev_close = aapl_close

