from AlgorithmImports import *

class QuantConnectAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {symbol: self.AddEquity(symbol, Resolution.Daily).Symbol for symbol in symbols}

        self.sma_period = 20
        self.rsi_period = 14

        self.closes = {symbol: [] for symbol in symbols}
        self.consecutive_red = {symbol: 0 for symbol in symbols}
        self.prev_spy_above_sma = None
        self.sold_spy_this_bar = False
        self.sold_aapl_this_bar = False

    def OnData(self, data):
        self.sold_spy_this_bar = False
        self.sold_aapl_this_bar = False

        for symbol_name in self.symbols:
            if self.symbols[symbol_name] not in data:
                return

        for symbol_name in self.symbols:
            symbol = self.symbols[symbol_name]
            close = data[symbol].Close
            self.closes[symbol_name].append(close)

        for symbol_name in self.symbols:
            if len(self.closes[symbol_name]) >= 2:
                if self.closes[symbol_name][-1] < self.closes[symbol_name][-2]:
                    self.consecutive_red[symbol_name] += 1
                else:
                    self.consecutive_red[symbol_name] = 0

        current_sma_spy = None
        if len(self.closes["SPY"]) >= self.sma_period:
            current_sma_spy = sum(self.closes["SPY"][-self.sma_period:]) / self.sma_period

        current_rsi_aapl = None
        if len(self.closes["AAPL"]) >= self.rsi_period + 1:
            current_rsi_aapl = self.calculate_rsi(self.closes["AAPL"][-self.rsi_period-1:])

        if current_sma_spy is None or current_rsi_aapl is None:
            return

        if self.prev_spy_above_sma is None:
            self.prev_spy_above_sma = self.closes["SPY"][-1] > current_sma_spy
            return

        spy_symbol = self.symbols["SPY"]
        aapl_symbol = self.symbols["AAPL"]
        spy_close = self.closes["SPY"][-1]
        aapl_close = self.closes["AAPL"][-1]

        spy_above_sma_now = spy_close > current_sma_spy

        if self.Portfolio[spy_symbol].Quantity > 0:
            if self.prev_spy_above_sma and not spy_above_sma_now:
                self.Liquidate(spy_symbol)
                self.sold_spy_this_bar = True

        if not self.sold_spy_this_bar and self.Portfolio[spy_symbol].Quantity == 0:
            if not self.prev_spy_above_sma and spy_above_sma_now:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                target_value = portfolio_value * 0.4
                shares_to_buy = int(target_value / spy_close)
                if shares_to_buy > 0:
                    self.Buy(spy_symbol, shares_to_buy)

        if self.Portfolio[aapl_symbol].Quantity > 0:
            if current_rsi_aapl > 60:
                self.Liquidate(aapl_symbol)
                self.sold_aapl_this_bar = True

        if not self.sold_aapl_this_bar and self.Portfolio[aapl_symbol].Quantity == 0:
            if self.consecutive_red["AAPL"] >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.Buy(aapl_symbol, shares_to_buy)

        self.prev_spy_above_sma = spy_above_sma_now

    def calculate_rsi(self, prices):
        deltas = [prices[i] - prices[i-1] for i in range(1, len(prices))]
        gains = sum(max(d, 0) for d in deltas)
        losses = sum(abs(min(d, 0)) for d in deltas)
        avg_gain = gains / self.rsi_period
        avg_loss = losses / self.rsi_period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

