class DualStrategyAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Add securities
        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.tickers:
            self.AddEquity(ticker, Resolution.Daily)

        # Strategy A (SPY) - SMA 20
        self.sma = SimpleMovingAverage(20)
        self.RegisterIndicator("SPY", self.sma, Resolution.Daily)

        # Strategy B (AAPL) - RSI 14
        self.rsi = RelativeStrengthIndex(14)
        self.RegisterIndicator("AAPL", self.rsi, Resolution.Daily)

        # Previous close tracking for AAPL consecutive red days
        self.prev_close_aapl = None
        self.consecutive_red_days = 0

        # Previous values for crossover detection
        self.prev_sma = None
        self.prev_spy_close = None

    def OnData(self, data):
        # Check if any ticker has missing data
        for ticker in self.tickers:
            if ticker not in data:
                return

        # Check if all required indicators are ready
        if not self.sma.IsReady or not self.rsi.IsReady:
            return

        # Get current prices
        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        # Update consecutive red days for AAPL
        if self.prev_close_aapl is not None:
            if aapl_close < self.prev_close_aapl:
                self.consecutive_red_days += 1
            else:
                self.consecutive_red_days = 0

        # Current holdings
        spy_holdings = self.Portfolio["SPY"].Quantity
        aapl_holdings = self.Portfolio["AAPL"].Quantity

        # Evaluate sells first
        # Strategy A sell: SPY close crosses below SMA
        if spy_holdings > 0:
            if self.prev_sma is not None and self.prev_spy_close is not None:
                if self.prev_spy_close >= self.prev_sma and spy_close < self.sma.Current.Value:
                    self.MarketOrder("SPY", -spy_holdings)

        # Strategy B sell: AAPL RSI > 60
        if aapl_holdings > 0:
            if self.rsi.Current.Value > 60:
                self.MarketOrder("AAPL", -aapl_holdings)

        # Evaluate buys
        # Strategy A buy: SPY close crosses above SMA
        if spy_holdings == 0:
            if self.prev_sma is not None and self.prev_spy_close is not None:
                if self.prev_spy_close <= self.prev_sma and spy_close > self.sma.Current.Value:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    invest_amount = portfolio_value * 0.4
                    shares_to_buy = int(invest_amount / spy_close)
                    if shares_to_buy > 0:
                        self.MarketOrder("SPY", shares_to_buy)

        # Strategy B buy: AAPL red for 3 consecutive days
        if aapl_holdings == 0:
            if self.consecutive_red_days >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.MarketOrder("AAPL", shares_to_buy)

        # Update previous values
        self.prev_close_aapl = aapl_close
        self.prev_sma = self.sma.Current.Value
        self.prev_spy_close = spy_close

