    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.symbols = {
            "SPY": self.AddEquity("SPY", Resolution.Daily).Symbol,
            "AAPL": self.AddEquity("AAPL", Resolution.Daily).Symbol,
            "IBM": self.AddEquity("IBM", Resolution.Daily).Symbol,
            "BAC": self.AddEquity("BAC", Resolution.Daily).Symbol,
            "AIG": self.AddEquity("AIG", Resolution.Daily).Symbol,
        }

        self.spy_sma = self.SMA(self.symbols["SPY"], 50, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.symbols["AAPL"], 14, Resolution.Daily)

        self.spy_closes = RollingWindow[float](2)
        self.spy_smas = RollingWindow[float](2)
        self.aapl_closes = RollingWindow[float](4)

        self.SetWarmUpPeriod(50)

    def OnData(self, data):
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        self.spy_closes.Add(self.Securities[self.symbols["SPY"]].Close)
        self.aapl_closes.Add(self.Securities[self.symbols["AAPL"]].Close)
        if self.spy_sma.IsReady:
            self.spy_smas.Add(self.spy_sma.Current.Value)

        if self.IsWarmingUp:
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return
        if self.spy_closes.Count < 2 or self.spy_smas.Count < 2 or self.aapl_closes.Count < 4:
            return

        self.EvaluateSells()
        self.EvaluateBuys()

    def EvaluateSells(self):
        spy_quantity = self.Portfolio[self.symbols["SPY"]].Quantity
        if spy_quantity > 0 and self.SPYCrossesBelow():
            self.MarketOrder(self.symbols["SPY"], -spy_quantity)

        aapl_quantity = self.Portfolio[self.symbols["AAPL"]].Quantity
        if aapl_quantity > 0 and self.aapl_rsi.Current.Value > 60:
            self.MarketOrder(self.symbols["AAPL"], -aapl_quantity)

    def EvaluateBuys(self):
        spy_quantity = self.Portfolio[self.symbols["SPY"]].Quantity
        if spy_quantity == 0 and self.SPYCrossesAbove():
            portfolio_value = self.Portfolio.TotalPortfolioValue
            investment = portfolio_value * 0.40
            spy_close = self.Securities[self.symbols["SPY"]].Close
            shares = int(investment / spy_close)
            if shares > 0:
                self.MarketOrder(self.symbols["SPY"], shares)

        aapl_quantity = self.Portfolio[self.symbols["AAPL"]].Quantity
        if aapl_quantity == 0 and self.AAPLRedFor3Days():
            cash = self.Portfolio.Cash
            if cash >= 20000:
                aapl_close = self.Securities[self.symbols["AAPL"]].Close
                shares = int(20000 / aapl_close)
                if shares > 0:
                    self.MarketOrder(self.symbols["AAPL"], shares)

    def SPYCrossesAbove(self):
        if self.spy_closes.Count < 2 or self.spy_smas.Count < 2:
            return False
        today_close = self.spy_closes[0]
        yesterday_close = self.spy_closes[1]
        today_sma = self.spy_smas[0]
        yesterday_sma = self.spy_smas[1]
        return yesterday_close <= yesterday_sma and today_close > today_sma

    def SPYCrossesBelow(self):
        if self.spy_closes.Count < 2 or self.spy_smas.Count < 2:
            return False
        today_close = self.spy_closes[0]
        yesterday_close = self.spy_closes[1]
        today_sma = self.spy_smas[0]
        yesterday_sma = self.spy_smas[1]
        return yesterday_close >= yesterday_sma and today_close < today_sma

    def AAPLRedFor3Days(self):
        if self.aapl_closes.Count < 4:
            return False
        red_1 = self.aapl_closes[2] < self.aapl_closes[3]
        red_2 = self.aapl_closes[1] < self.aapl_closes[2]
        red_3 = self.aapl_closes[0] < self.aapl_closes[1]
        return red_1 and red_2 and red_3

