class SPYAAPLStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in tickers:
            self.AddEquity(ticker, Resolution.Daily)

        self.spy_sma = self.SMA("SPY", 50)
        self.aapl_rsi = self.RSI("AAPL", 14)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

        self.prev_spy_close = None
        self.prev_spy_sma = None

        self.aapl_red_count = 0
        self.prev_aapl_close = None

    def OnData(self, data):
        required = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        if not all(data.ContainsKey(ticker) for ticker in required):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_count += 1
            else:
                self.aapl_red_count = 0

        if self.strategy_a_shares > 0:
            if (self.prev_spy_close is not None and 
                self.prev_spy_close > self.prev_spy_sma and 
                spy_close <= self.spy_sma.Current.Value):
                self.Liquidate("SPY")
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            if self.aapl_rsi.Current.Value > 60:
                self.Liquidate("AAPL")
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            if (self.prev_spy_close is not None and 
                self.prev_spy_close <= self.prev_spy_sma and 
                spy_close > self.spy_sma.Current.Value):
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                shares_to_buy = int(invest_amount / spy_close)
                if shares_to_buy > 0:
                    self.MarketOrder("SPY", shares_to_buy)
                    self.strategy_a_shares = shares_to_buy

        if self.strategy_b_shares == 0:
            if self.aapl_red_count >= 3:
                if self.Portfolio.Cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.MarketOrder("AAPL", shares_to_buy)
