from AlgorithmImports import *

class QuantConnectLEANAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to equities at daily resolution
        self.symbols = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbol_objects = {}

        for symbol in self.symbols:
            equity = self.AddEquity(symbol, Resolution.Daily)
            self.symbol_objects[symbol] = equity.Symbol

        # Price history tracking
        self.closes = {symbol: [] for symbol in self.symbols}

        # Strategy A (SPY) - moving average period
        self.strategy_a_ma_period = 20

        # Strategy B (AAPL) - RSI period and red day counter
        self.strategy_b_red_count = 0
        self.strategy_b_rsi_period = 14

    def OnData(self, data):
        # Check if all required bars are available
        for symbol in self.symbols:
            if symbol not in data or not data[symbol]:
                return

        # Update close history
        for symbol in self.symbols:
            self.closes[symbol].append(data[symbol].Close)

        # Check if we have enough history for indicators
        if len(self.closes['SPY']) < self.strategy_a_ma_period + 1:
            return
        if len(self.closes['AAPL']) < self.strategy_b_rsi_period + 1:
            return

        # Get current prices
        spy_close = data['SPY'].Close
        aapl_close = data['AAPL'].Close

        # Update state tracking for red days
        self._strategy_b_red_tracking(aapl_close)

        # Evaluate sell rules before buy rules
        self._strategy_a_sell(spy_close)
        self._strategy_b_sell(aapl_close)

        # Evaluate buy rules
        self._strategy_a_buy(spy_close)
        self._strategy_b_buy(aapl_close)

    def _get_rsi(self, closes_list, period):
        if len(closes_list) < period + 1:
            return None

        recent_closes = closes_list[-(period+1):]
        gains = 0.0
        losses = 0.0

        for i in range(1, len(recent_closes)):
            diff = recent_closes[i] - recent_closes[i-1]
            if diff > 0:
                gains += diff
            else:
                losses -= diff

        avg_gain = gains / period
        avg_loss = losses / period

        if avg_loss == 0:
            return 100.0 if avg_gain > 0 else 50.0

        rs = avg_gain / avg_loss
        rsi = 100.0 - (100.0 / (1.0 + rs))
        return rsi

    def _strategy_a_sell(self, spy_close):
        if self.Securities['SPY'].Holdings.Quantity <= 0:
            return

        # Calculate today's and yesterday's moving averages
        spy_ma_today = sum(self.closes['SPY'][-self.strategy_a_ma_period:]) / self.strategy_a_ma_period
        spy_ma_yesterday = sum(self.closes['SPY'][-(self.strategy_a_ma_period + 1):-1]) / self.strategy_a_ma_period
        spy_close_yesterday = self.closes['SPY'][-2]

        # Check cross below: yesterday >= MA, today < MA
        if spy_close_yesterday >= spy_ma_yesterday and spy_close < spy_ma_today:
            quantity = self.Securities['SPY'].Holdings.Quantity
            if quantity > 0:
                self.Sell(self.symbol_objects['SPY'], quantity)

    def _strategy_a_buy(self, spy_close):
        if self.Securities['SPY'].Holdings.Quantity > 0:
            return

        # Calculate today's and yesterday's moving averages
        spy_ma_today = sum(self.closes['SPY'][-self.strategy_a_ma_period:]) / self.strategy_a_ma_period
        spy_ma_yesterday = sum(self.closes['SPY'][-(self.strategy_a_ma_period + 1):-1]) / self.strategy_a_ma_period
        spy_close_yesterday = self.closes['SPY'][-2]

        # Check cross above: yesterday <= MA, today > MA
        if spy_close_yesterday <= spy_ma_yesterday and spy_close > spy_ma_today:
            portfolio_value = self.Portfolio.TotalPortfolioValue
            invest_amount = portfolio_value * 0.40
            shares = int(invest_amount / spy_close)

            if shares > 0:
                self.Buy(self.symbol_objects['SPY'], shares)

    def _strategy_b_red_tracking(self, aapl_close):
        if len(self.closes['AAPL']) < 2:
            self.strategy_b_red_count = 0
            return

        aapl_close_yesterday = self.closes['AAPL'][-2]

        if aapl_close < aapl_close_yesterday:
            self.strategy_b_red_count += 1
        else:
            self.strategy_b_red_count = 0

    def _strategy_b_sell(self, aapl_close):
        if self.Securities['AAPL'].Holdings.Quantity <= 0:
            return

        aapl_rsi = self._get_rsi(self.closes['AAPL'], self.strategy_b_rsi_period)

        if aapl_rsi is None:
            return

        if aapl_rsi > 60:
            quantity = self.Securities['AAPL'].Holdings.Quantity
            if quantity > 0:
                self.Sell(self.symbol_objects['AAPL'], quantity)

    def _strategy_b_buy(self, aapl_close):
        if self.Securities['AAPL'].Holdings.Quantity > 0:
            return

        if self.strategy_b_red_count >= 3:
            available_cash = self.Portfolio.Cash
            if available_cash >= 20000:
                shares = int(20000 / aapl_close)
                if shares > 0:
                    self.Buy(self.symbol_objects['AAPL'], shares)

