                self.MarketOrder(self.symbols["SPY"], -spy_holdings)

        if aapl_rsi > 60:
            if aapl_holdings > 0:
                self.MarketOrder(self.symbols["AAPL"], -aapl_holdings)

        if self.spy_prev_close <= self.spy_prev_ma and spy_close > spy_ma:
            if spy_holdings == 0:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                invest_amount = portfolio_value * 0.4
                shares_to_buy = int(invest_amount / spy_close)
                if shares_to_buy > 0:
                    self.MarketOrder(self.symbols["SPY"], shares_to_buy)

        if self.aapl_consecutive_red_days >= 3:
            if aapl_holdings == 0:
                if self.Portfolio.Cash >= 20000:
                    shares_to_buy = int(20000 / aapl_close)
                    if shares_to_buy > 0:
                        self.MarketOrder(self.symbols["AAPL"], shares_to_buy)

        self.spy_prev_close = spy_close
        self.spy_prev_ma = spy_ma

    def calculate_rsi(self, prices, period):
        if len(prices) < period + 1:
            return None

        deltas = [prices[i] - prices[i-1] for i in range(1, len(prices))]
        gains = [d if d > 0 else 0 for d in deltas]
        losses = [-d if d < 0 else 0 for d in deltas]

        avg_gain = sum(gains[-period:]) / period
        avg_loss = sum(losses[-period:]) / period

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 50

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))

        return rsi
