    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        for ticker in self.tickers:
            self.AddEquity(ticker, Resolution.Daily)

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

        self.prev_spy_close = None
        self.prev_aapl_close = None
        self.prev_spy_sma = None

        self.spy_sma100 = SimpleMovingAverage(100)
        self.aapl_rsi14 = RelativeStrengthIndex(14)

        self.aapl_red_streak = 0

        self.SetWarmUp(100)

    def OnData(self, data):
        for ticker in self.tickers:
            if ticker not in data or data[ticker] is None:
                return

        spy_close = data["SPY"].Close
        aapl_close = data["AAPL"].Close

        self.spy_sma100.Update(data["SPY"].EndTime, spy_close)
        self.aapl_rsi14.Update(data["AAPL"].EndTime, aapl_close)

        if self.prev_aapl_close is not None:
            if aapl_close < self.prev_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        if self.IsWarmingUp:
            self.prev_spy_close = spy_close
            self.prev_aapl_close = aapl_close
            if self.spy_sma100.IsReady:
                self.prev_spy_sma = self.spy_sma100.Current.Value
            return

        self.EvaluateSells(data)
        self.EvaluateBuys(data)

        self.prev_spy_close = spy_close
        self.prev_aapl_close = aapl_close
        self.prev_spy_sma = self.spy_sma100.Current.Value

    def EvaluateSells(self, data):
        if self.strategy_a_lot > 0:
            if self.CheckSellA(data):
                self.MarketOrder("SPY", -self.strategy_a_lot)
                self.strategy_a_lot = 0

        if self.strategy_b_lot > 0:
            if self.CheckSellB(data):
                self.MarketOrder("AAPL", -self.strategy_b_lot)
                self.strategy_b_lot = 0

    def EvaluateBuys(self, data):
        if self.strategy_a_lot == 0:
            if self.CheckBuyA(data):
                portfolio_value = self.Portfolio.TotalPortfolioValue
                amount = portfolio_value * 0.40
                close = data["SPY"].Close
                shares = int(amount / close)
                if shares > 0:
                    self.MarketOrder("SPY", shares)
                    self.strategy_a_lot = shares

        if self.strategy_b_lot == 0:
            if self.CheckBuyB():
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    close = data["AAPL"].Close
                    shares = int(20000 / close)
                    if shares > 0:
                        self.MarketOrder("AAPL", shares)
                        self.strategy_b_lot = shares

    def CheckBuyA(self, data):
        if not self.spy_sma100.IsReady:
            return False
        if self.prev_spy_close is None or self.prev_spy_sma is None:
            return False

        curr_close = data["SPY"].Close
        curr_sma = self.spy_sma100.Current.Value

        return self.prev_spy_close <= self.prev_spy_sma and curr_close > curr_sma

    def CheckSellA(self, data):
        if not self.spy_sma100.IsReady:
            return False
        if self.prev_spy_close is None or self.prev_spy_sma is None:
            return False

        curr_close = data["SPY"].Close
        curr_sma = self.spy_sma100.Current.Value

        return self.prev_spy_close >= self.prev_spy_sma and curr_close < curr_sma

    def CheckBuyB(self):
        if not self.aapl_rsi14.IsReady:
            return False
        return self.aapl_red_streak >= 3

    def CheckSellB(self, data):
        if not self.aapl_rsi14.IsReady:
            return False
        rsi = self.aapl_rsi14.Current.Value
        return rsi > 60

