    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {}
        for ticker in self.tickers:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        self.closes = {ticker: [] for ticker in self.tickers}

        self.spy_shares = 0
        self.aapl_shares = 0
        self.aapl_red_days = 0
        self.bar_count = 0

    def OnData(self, data):
        for ticker in self.tickers:
            if self.symbols[ticker] not in data:
                return

        for ticker in self.tickers:
            self.closes[ticker].append(data[self.symbols[ticker]].Close)

        self.bar_count += 1

        if self.bar_count < 100:
            return

        spy_close = self.closes["SPY"][-1]
        spy_prev_close = self.closes["SPY"][-2]
        aapl_close = self.closes["AAPL"][-1]
        aapl_prev_close = self.closes["AAPL"][-2]

        spy_sma = sum(self.closes["SPY"][-100:]) / 100

        if aapl_close < aapl_prev_close:
            self.aapl_red_days += 1
        else:
            self.aapl_red_days = 0

        aapl_rsi = None
        if len(self.closes["AAPL"]) >= 14:
            aapl_rsi = self._calculate_rsi(self.closes["AAPL"][-14:])

        if self.spy_shares > 0:
            if spy_prev_close > spy_sma and spy_close < spy_sma:
                self.Sell(self.symbols["SPY"], self.spy_shares)
                self.spy_shares = 0

        if self.aapl_shares > 0:
            if aapl_rsi is not None and aapl_rsi > 60:
                self.Sell(self.symbols["AAPL"], self.aapl_shares)
                self.aapl_shares = 0

        if self.spy_shares == 0:
            if spy_prev_close <= spy_sma and spy_close > spy_sma:
                portfolio_value = self.Portfolio.TotalPortfolioValue
                investment = portfolio_value * 0.40
                shares = int(investment / spy_close)
                if shares > 0:
                    self.Buy(self.symbols["SPY"], shares)
                    self.spy_shares = shares

        if self.aapl_shares == 0:
            if self.aapl_red_days >= 3:
                cash = self.Portfolio.Cash
                if cash >= 20000:
                    shares = int(20000 / aapl_close)
                    if shares > 0:
                        self.Buy(self.symbols["AAPL"], shares)
                        self.aapl_shares = shares

    def _calculate_rsi(self, recent_closes):
        if len(recent_closes) < 2:
            return None

        gains = 0.0
        losses = 0.0

        for i in range(1, len(recent_closes)):
            change = recent_closes[i] - recent_closes[i-1]
            if change > 0:
                gains += change
            else:
                losses -= change

        num_changes = len(recent_closes) - 1
        avg_gain = gains / num_changes
        avg_loss = losses / num_changes

        if avg_loss == 0:
            return 100 if avg_gain > 0 else 0

        rs = avg_gain / avg_loss
        rsi = 100 - (100 / (1 + rs))
        return rsi

