    def Initialize(self):
        self.SetStartDate(2006, 1, 3)
        self.SetEndDate(2015, 12, 31)
        self.SetCash(1000000)

        # Subscribe to equities
        self.symbols = {}
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            self.symbols[ticker] = self.AddEquity(ticker, Resolution.Daily).Symbol

        # Strategy A (SPY)
        self.strategy_a_lot = 0

        # Strategy B (AAPL)
        self.strategy_b_lot = 0
        self.aapl_red_days = 0

        # Price history
        self.last_spy_close = None
        self.last_aapl_close = None
        self.prev_spy_sma = None

        # Indicators
        self.spy_sma = self.SMA(self.symbols["SPY"], 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(self.symbols["AAPL"], 14, Resolution.Daily)

    def OnData(self, data):
        # Skip if any symbol is missing
        for ticker in ["SPY", "AAPL", "IBM", "BAC", "AIG"]:
            if not data.ContainsKey(self.symbols[ticker]):
                return

        # Skip if indicators are not ready
        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        # Get current prices and indicators
        curr_spy_close = data[self.symbols["SPY"]].Close
        curr_aapl_close = data[self.symbols["AAPL"]].Close
        curr_spy_sma = self.spy_sma.Current.Value
        curr_aapl_rsi = self.aapl_rsi.Current.Value

        # Track consecutive red days for AAPL
        if self.last_aapl_close is not None:
            if curr_aapl_close < self.last_aapl_close:
                self.aapl_red_days += 1
            else:
                self.aapl_red_days = 0
        else:
            self.aapl_red_days = 0

        # --- SELL PHASE ---

        # Strategy B: Sell when RSI > 60
        if self.strategy_b_lot > 0:
            if curr_aapl_rsi > 60:
                self.Liquidate(self.symbols["AAPL"])
                self.strategy_b_lot = 0

        # Strategy A: Sell when crosses below SMA
        if self.strategy_a_lot > 0:
            if self.last_spy_close is not None and self.prev_spy_sma is not None:
                if self.last_spy_close > self.prev_spy_sma and curr_spy_close <= curr_spy_sma:
                    self.Liquidate(self.symbols["SPY"])
                    self.strategy_a_lot = 0

        # --- BUY PHASE ---

        # Strategy A: Buy when crosses above SMA
        if self.strategy_a_lot == 0:
            if self.last_spy_close is not None and self.prev_spy_sma is not None:
                if self.last_spy_close <= self.prev_spy_sma and curr_spy_close > curr_spy_sma:
                    portfolio_value = self.Portfolio.TotalPortfolioValue
                    invest_amount = portfolio_value * 0.4
                    shares_to_buy = int(invest_amount / curr_spy_close)
                    if shares_to_buy > 0:
                        self.Buy(self.symbols["SPY"], shares_to_buy)
                        self.strategy_a_lot = shares_to_buy

        # Strategy B: Buy when 3 consecutive red days
        if self.strategy_b_lot == 0:
            if self.aapl_red_days >= 3:
                available_cash = self.Portfolio.Cash
                if available_cash >= 20000:
                    shares_to_buy = int(20000 / curr_aapl_close)
                    if shares_to_buy > 0:
                        self.Buy(self.symbols["AAPL"], shares_to_buy)
                        self.strategy_b_lot = shares_to_buy

        # Update for next bar
        self.last_spy_close = curr_spy_close
        self.last_aapl_close = curr_aapl_close
        self.prev_spy_sma = curr_spy_sma

