        # Strategy A: Sell when crosses below SMA
        if self.strategy_a_lot > 0:
            if self.last_spy_close is not None and self.prev_spy_sma is not None:
                if self.last_spy_close > self.prev_spy_sma and curr_spy_close <= curr_spy_sma:
